export const BODY: string = "\n<p>فریم تصویر کے گرد وہ کنارہ ہے جو اسے مکمل کرتا ہے۔ اچھا فریم تصویر کو نمایاں کرتا ہے، جبکہ غلط فریم توجہ خود کھینچ کر تصویر کو پیچھے کر دیتا ہے۔</p>\n<p>فریم صرف سجاوٹ نہیں، یہ تصویر کی پیشکش کا حصہ ہے۔ گیلری کی تصویر، سوشل پوسٹ اور مصنوعات کی تصویر، تینوں کو الگ انداز کا فریم چاہیے۔</p>\n<p>یہ مضمون کم سے کم، پولرائڈ، گیلری، گریڈینٹ اور دیگر انداز، رنگوں کا نظریہ اور ہر کام کے لیے درست انتخاب بتاتا ہے۔ فریم لگانے کے لیے <a href=\"/ur/tasveer-par-border-lagayein/\">امیج بارڈر جنریٹر</a> کھولیں۔</p>\n<h2 id=\"why-frames-matter\">فریم کیوں اہم ہیں</h2>\n<p>فریم تصویر کو اس کے ارد گرد سے الگ کرتا ہے، خاص طور پر سفید پس منظر پر۔ بغیر فریم کے سفید تصویر سفید صفحے میں گم ہو جاتی ہے، اور فریم اسے حد دیتا ہے۔</p>\n<p>فریم تصویر کے مزاج کو بھی طے کرتا ہے: پتلی سیاہ لکیر پیشہ ورانہ، موٹا سفید حاشیہ گیلری جیسا، اور رنگین چمک کھیل والا احساس دیتی ہے۔</p>\n<h2 id=\"minimal-frames\">کم سے کم فریم: کم ہی زیادہ ہے</h2>\n<p>کم سے کم فریم پتلی اور سادہ ہوتی ہے، اکثر صرف ایک یا دو پکسلز کی سیاہ یا سرمئی لکیر۔ یہ تصویر کو حد دیتی ہے بغیر خود توجہ کھینچے۔</p>\n<p>یہ انداز پیشہ ورانہ پورٹ فولیو، دستاویزات اور مصنوعات کی تصویروں کے لیے بہترین ہے۔ جب تصویر خود مضبوط ہو تو فریم کو خاموش رہنا چاہیے۔</p>\n<h2 id=\"polaroid-and-retro\">پولرائڈ اور پرانے انداز کے فریم</h2>\n<p>پولرائڈ فریم میں نیچے موٹا سفید حصہ ہوتا ہے، جہاں اکثر کیپشن لکھا جاتا ہے۔ یہ فوری کیمرے کی یاد دلاتا ہے اور تصویر کو ذاتی اور گرم احساس دیتا ہے۔</p>\n<p>یہ انداز شادی، سفر اور خاندانی تصویروں کے لیے اچھا ہے، مگر کاروباری پیشکش میں بچکانہ لگ سکتا ہے۔ پولرائڈ کو وہیں استعمال کریں جہاں یادیں اصل بات ہوں۔</p>\n<h2 id=\"gallery-frames\">گیلری فریم: میٹ والا انداز</h2>\n<p>گیلری فریم میں تصویر کے گرد چوڑا سفید یا ہلکا میٹ ہوتا ہے، جیسے نمائش میں لگی تصویر۔ یہ تصویر کو سانس لینے کی جگہ دیتا ہے اور اسے اہم محسوس کراتا ہے۔</p>\n<p>میٹ کا رنگ تصویر کے سب سے ہلکے حصے سے ملنا چاہیے، تاکہ تضاد نرم رہے۔ بہت چوڑا میٹ چھوٹی تصویر کو دبا دیتا ہے، اس لیے تناسب کا خیال رکھیں۔</p>\n<h2 id=\"gradient-and-glow\">گریڈینٹ اور چمک والے فریم</h2>\n<p>گریڈینٹ فریم ایک رنگ سے دوسرے رنگ میں بدلتا ہے، جو جدید اور توانا لگتا ہے۔ چمک والا فریم تصویر کے گرد نرم روشنی بکھیرتا ہے، جیسے تصویر روشن ہو۔</p>\n<p>یہ انداز سوشل میڈیا اور کھیلوں کے گرافکس کے لیے اچھا ہے، مگر سنجیدہ کام میں توجہ بٹاتا ہے۔ گریڈینٹ کو تصویر کے رنگوں سے ملائیں، ان سے ٹکرانے نہ دیں۔</p>\n<h2 id=\"frames-for-social\">سوشل میڈیا کے لیے فریم</h2>\n<p>سوشل میڈیا پر فریم تصویر کو فیڈ میں نمایاں کرتا ہے، خاص طور پر جب فیڈ میں سب تصویریں ایک جیسی ہوں۔ مستقل فریم آپ کی فیڈ کو پہچان بھی دیتا ہے۔</p>\n<p>سوشل فریم زیادہ موٹا نہیں ہونا چاہیے، کیونکہ موبائل پر تصویر پہلے ہی چھوٹی ہوتی ہے۔ پتلی مگر واضح لکیر کافی ہے، اور رنگ برانڈ سے ملنا چاہیے۔</p>\n<h2 id=\"frames-for-print\">پرنٹ کے لیے فریم</h2>\n<p>پرنٹ میں فریم کاغذ کے کنارے سے محفوظ فاصلے پر ہونا چاہیے، کیونکہ پرنٹر کنارے تراش سکتا ہے۔ حاشیہ چھوڑے بغیر لگایا گیا فریم پرنٹ میں آدھا کٹ سکتا ہے۔</p>\n<p>پرنٹ کے لیے سادہ اور کلاسک فریم بہتر ہیں، کیونکہ وہ سالوں تک اچھے لگتے ہیں۔ چمک اور گریڈینٹ پرنٹ میں اکثر دھندلے یا عجیب رنگ کے نکلتے ہیں۔</p>\n<h2 id=\"frames-for-products\">مصنوعات کی تصویروں کے لیے فریم</h2>\n<p>مصنوعات کی تصویر میں فریم کو مصنوعات سے مقابلہ نہیں کرنا چاہیے۔ سفید یا ہلکی سرمئی پتلی لکیر مصنوعات کو صاف اور قابل اعتماد دکھاتی ہے۔</p>\n<p>پوری کیٹلاگ میں ایک ہی فریم رکھیں، تاکہ دکان منظم لگے۔ ہر مصنوعات پر الگ فریم دکان کو بے ترتیب اور غیر پیشہ ورانہ بنا دیتا ہے۔</p>\n<h2 id=\"frames-for-portraits\">پورٹریٹ کے لیے فریم</h2>\n<p>پورٹریٹ میں فریم چہرے کی طرف توجہ لے جانے والا ہونا چاہیے، نہ کہ اس سے توجہ ہٹانے والا۔ نرم سفید یا ہلکا بھورا فریم جلد کے رنگوں کے ساتھ اچھا لگتا ہے۔</p>\n<p>سیاہ فریم ڈرامائی پورٹریٹ کو مضبوط کرتا ہے، مگر روشن اور خوشگوار پورٹریٹ پر بھاری لگتا ہے۔ فریم کا رنگ تصویر کے مزاج سے چنیں۔</p>\n<h2 id=\"frames-for-screenshots\">اسکرین شاٹ کے لیے فریم</h2>\n<p>اسکرین شاٹ پر فریم اسے دستاویز یا پیشکش میں نمایاں کرتا ہے۔ ہلکی سرمئی لکیر اسکرین شاٹ کو صفحے سے الگ کرتی ہے، بغیر متن کو متاثر کیے۔</p>\n<p>اسکرین شاٹ کا فریم کبھی موٹا نہیں ہونا چاہیے، کیونکہ متن پہلے ہی چھوٹا ہوتا ہے۔ مقصد صرف حد دینا ہے، سجاوٹ نہیں۔</p>\n<h2 id=\"colour-theory\">فریم کے لیے رنگوں کا نظریہ</h2>\n<p>فریم کا رنگ تصویر کے کسی رنگ سے ملنا چاہیے، یا اس کے مخالف رنگ سے۔ ملتا ہوا رنگ ہم آہنگی دیتا ہے، جبکہ مخالف رنگ تضاد سے تصویر کو نمایاں کرتا ہے۔</p>\n<p>تصویر میں نہ ہونے والا تیز رنگ فریم کے لیے نہ چنیں، کیونکہ وہ تصویر سے ٹکراتا ہے۔ فریم کا رنگ تصویر کے سب سے پرسکون حصے سے لینا محفوظ طریقہ ہے۔</p>\n<h2 id=\"shadow-and-depth\">سایہ اور گہرائی</h2>\n<p>ہلکا سایہ فریم کو صفحے سے اوپر اٹھا ہوا دکھاتا ہے، جس سے تصویر میں گہرائی آتی ہے۔ بہت گہرا سایہ تصویر کو بھاری اور پرانا بنا دیتا ہے۔</p>\n<p>سایہ نرم اور ہلکا رکھیں، اور صرف ایک طرف سے آنے والی روشنی کی نقل کریں۔ یکساں چاروں طرف کا سایہ غیر فطری لگتا ہے۔</p>\n<h2 id=\"rounded-vs-square\">گول بمقابلہ مربع فریم</h2>\n<p>مربع کونے سنجیدہ اور کلاسک لگتے ہیں، جبکہ گول کونے نرم اور جدید محسوس ہوتے ہیں۔ ایپ اور ویب گرافکس میں گول کونے عام ہیں، جبکہ پرنٹ میں مربع کونے زیادہ چلتے ہیں۔</p>\n<p>گول کونوں کا رداس تصویر کے سائز سے ملنا چاہیے: چھوٹی تصویر پر بڑا رداس تصویر کو دائرہ بنا دیتا ہے، جبکہ بڑی تصویر پر چھوٹا رداس نظر ہی نہیں آتا۔</p>\n<h2 id=\"mixing-frame-and-border\">فریم کو دیگر ایڈٹس کے ساتھ ملانا</h2>\n<p>فریم کو کراپ، فلٹر یا متن کے ساتھ ملاتے وقت ترتیب اہم ہے: پہلے کراپ کریں، پھر فلٹر لگائیں، اور آخر میں فریم لگائیں۔ فریم کے بعد تصویر کاٹنے سے فریم بھی کٹ جاتا ہے۔</p>\n<p>ایک تصویر پر ایک ہی فریم کافی ہے۔ فریم کے اندر فریم لگانے سے تصویر چھوٹی اور الجھی ہوئی لگتی ہے۔</p>\n<h2 id=\"trends-vs-timeless\">رجحان بمقابلہ ہمیشہ چلنے والا انداز</h2>\n<p>فریم کے رجحان تیزی سے بدلتے ہیں: کبھی موٹے رنگین فریم چلتے ہیں، کبھی پتلی لکیر۔ رجحان والی فریم چند مہینوں میں پرانی لگنے لگتی ہے۔</p>\n<p>اہم کام کے لیے ہمیشہ چلنے والا انداز چنیں: پتلی سیاہ یا سفید لکیر کبھی پرانی نہیں ہوتی۔ کھیل کے لیے رجحان آزمائیں، مگر پورٹ فولیو کے لیے کلاسک رکھیں۔</p>\n<h2 id=\"choosing-cheat-sheet\">فریم چننے کی فوری یاد دہانی</h2>\n<p>پیشہ ورانہ کام کے لیے پتلی سیاہ یا سرمئی لکیر، گیلری کے لیے چوڑا سفید میٹ، اور سوشل میڈیا کے لیے برانڈ رنگ کی پتلی لکیر چنیں۔ پولرائڈ صرف ذاتی تصویروں کے لیے رکھیں۔</p>\n<p>شک ہو تو سب سے سادہ فریم چنیں۔ سادہ فریم کبھی غلط نہیں ہوتا، جبکہ جرات مندانہ فریم غلط جگہ پر پوری تصویر خراب کر دیتا ہے۔</p>\n<h2 id=\"frames-for-events\">تقریبات کے اعلانات کے لیے فریم</h2>\n<p>تقریب کے اعلان میں فریم کو تقریب کے مزاج سے ملنا چاہیے: شادی کے لیے نرم سنہری، سالگرہ کے لیے رنگین، اور کاروباری تقریب کے لیے سادہ سیاہ۔</p>\n<p>اعلان کی تصویر میں فریم کے اندر تاریخ اور جگہ کے لیے جگہ چھوڑیں۔ فریم اتنا موٹا نہ ہو کہ متن کے لیے جگہ نہ بچے۔ بارڈر لگانے کے عملی مراحل <a href=\"/ur/blog/tasveer-par-border-kaise-lagayein/\">تصویر پر بارڈر کیسے لگائیں</a> اور مکمل رہنما <a href=\"/ur/blog/tasveer-border-generator-rehnumai/\">امیج بارڈر جنریٹر رہنما</a> میں دیکھیں۔ کونے گول کرنے ہوں تو <a href=\"/ur/tasveer-ke-kone-gol-karein/\">کونے گول کریں</a>۔</p>\n";

